def cards(text):
    return {m[1]:m[2] for m in re.finditer(r'^### ([^\n]+)\n(.*?)(?=^#{2,3} |\Z)',text,re.M|re.S) if 'Статус:' in m[2]}
before=cards(s);assert len(before)==221
def update(id,note,status=None):
    global s
    pat=rf'(^### {re.escape(id)}\n)(.*?)(?=^#{{2,3}} |\Z)'
    def change(m):
        body=re.sub(r'Обновлено: \*\*[^*]+\*\*','Обновлено: **2026-10-18**',m[2],count=1)
        if status:body=re.sub(r'Статус: \*\*[^*]+\*\*',f'Статус: **{status}**',body,count=1)
        return m[1]+body.rstrip()+f'\n\n- Дополнение LOG-20261018-05: {note} [Отчёт]({REPORT}); [доказательства]({EVID}/evidence.json).\n\n'
    s,n=re.subn(pat,change,s,count=1,flags=re.M|re.S);assert n==1,id
    if status:
        s,n=re.subn(rf'^(\| \[{re.escape(id)}\]\(#[^)]*\).*\| )[^|]+ \|$',rf'\g<1>{status} |',s,flags=re.M);assert n>=1,id
